package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import org.w3c.dom.Attr
import org.w3c.dom.Element
import org.w3c.dom.NamedNodeMap
import org.w3c.dom.Node

class NamespaceDetector : Detector(), XmlScanner {

    override fun visitDocument(context: XmlContext) {
        val root = context.document.documentElement ?: return
        val declarations = mutableMapOf<String, MutableList<Attr>>()
        val defaultDeclarations = mutableListOf<Attr>()
        val usedPrefixes = mutableSetOf<String>()
        var defaultUsed = false

        fun visitElement(element: Element) {
            // element prefix/namespace usage
            val prefix = element.prefix?.takeIf { it.isNotEmpty() }
            if (prefix != null) {
                usedPrefixes.add(prefix)
            } else if (element.namespaceURI?.isNotEmpty() == true) {
                defaultUsed = true
            }

            val attrs = element.attributes
            for (i in 0 until attrs.length) {
                val attr = attrs.item(i) as? Attr ?: continue
                val attrName = attr.name
                if (attrName.startsWith("xmlns:")) {
                    val declaredPrefix = attrName.substringAfter("xmlns:")
                    declarations.getOrPut(declaredPrefix) { mutableListOf() }.add(attr)
                } else if (attrName == "xmlns") {
                    defaultDeclarations.add(attr)
                } else {
                    val attrPrefix = attr.prefix?.takeIf { it.isNotEmpty() }
                    if (attrPrefix != null) {
                        usedPrefixes.add(attrPrefix)
                    }
                }
            }

            // traverse children
            var child = element.firstChild
            while (child != null) {
                if (child.nodeType == Node.ELEMENT_NODE) {
                    visitElement(child as Element)
                }
                child = child.nextSibling
            }
        }

        visitElement(root)

        for ((prefix, attrs) in declarations) {
            if (prefix !in usedPrefixes) {
                for (attr in attrs) {
                    context.report(
                        ISSUE,
                        attr,
                        context.getLocation(attr),
                        "Unused namespace declaration: `$prefix`"
                    )
                }
            }
        }
        if (!defaultUsed) {
            for (attr in defaultDeclarations) {
                context.report(
                    ISSUE,
                    attr,
                    context.getLocation(attr),
                    "Unused namespace declaration: default namespace"
                )
            }
        }
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "UnusedNamespace",
            briefDescription = "Unused namespace",
            explanation = "Unused namespace declarations take up space and require processing that is not necessary.",
            category = Category.PERFORMANCE,
            priority = 3,
            severity = Severity.WARNING,
            implementation = Implementation(NamespaceDetector::class.java, Scope.RESOURCE_FILE_SCOPE)
        )
    }
}
```

